"""Independent teaching sequence following mathematical sections 22.1–22.4."""
import re
import sympy as s
lessons=[];models=[]
x,t,n=s.symbols('x t n',real=True)
def T(v):return s.latex(s.sympify(v))
def fmt(text):
 chunks=re.split(r'(\\\[.*?\\\]|\\\(.*?\\\))',text,flags=re.S);table=str.maketrans('⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿʸ','-0123456789ny')
 for i in range(0,len(chunks),2):chunks[i]=re.sub(r'(?:[A-Za-zλ][⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿʸ]+)+',lambda m:r'\('+re.sub(r'([A-Za-zλ])([⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿʸ]+)',lambda z:z[1]+'^{'+z[2].translate(table)+'}',m[0])+r'\)',chunks[i])
 return ''.join(chunks)
def D(*rows):return r'\[\begin{gathered}'+r'\\'.join(rows)+r'\end{gathered}\]'
def E(code,title,question,solution,kind,**data):
 uid='FINT-E-'+code;models.append(dict(id=uid,kind=kind,**data))
 return dict(title=title,question=fmt(question),solution=fmt(solution),verification=uid)
def L(key,title,summary,objective,before,ideas,method,mistakes,examples):
 lessons.append(dict(key=key,id='fp2_integration_'+key,title=title,summary=summary,objective=objective,before=fmt(before),ideas=fmt(ideas),method='<ol>'+''.join('<li>'+fmt(z)+'</li>' for z in method)+'</ol>',mistakes=mistakes,examples=examples))
base='/courses/maths4u-9231-fp2/topics/fp2_integration_'
def before(key):return '<p>Complete <a href="'+base+key+'">the preceding lesson</a>. Retain exact values until the final numerical step.</p>'
L('techniques','Further integration techniques','Choose a substitution or a standard inverse-function form.',
 'Evaluate integrals with quadratic roots and hyperbolic substitutions, including endpoint limits.',
 '<p>Review substitution, integration by parts and partial fractions from Pure Mathematics. Complete <a href="/courses/maths4u-9231-fp2/topics/fp2_hyperbolic_inverse">inverse hyperbolic functions</a> and the chain rule. Mean values and volumes used in some written problems are prerequisite applications, not new Further Mathematics requirements.</p>',
 r'''<h3>Recognise the expression under the root</h3><p>Complete the square before choosing a substitution. For a positive constant a, the three common patterns are a²−u², a²+u² and u²−a². Real domains and the positive square root determine the useful branch.</p>'''+D(r'\int\frac{du}{\sqrt{a^2-u^2}}=\sin^{-1}\frac ua+C',r'\int\frac{du}{\sqrt{a^2+u^2}}=\sinh^{-1}\frac ua+C',r'\int\frac{du}{\sqrt{u^2-a^2}}=\cosh^{-1}\frac ua+C\quad(u>a)')+r'''<p>For u&lt;−a the last expression needs a different branch or a logarithmic absolute-value form. A standard form in u still requires the factor from du/dx.</p><h3>Make the radical manageable</h3><p>Use u=a sin v for a circular root and u=a sinh v for a sum of squares. For u²−a² on u≥a, use u=a cosh v with v≥0. Then sqrt(sinh²v)=sinh v on that branch. Transform both endpoints together with the differential.</p><h3>Improper does not automatically mean divergent</h3><p>If the integrand is unbounded at an endpoint, first integrate over a shorter interval and then take its one-sided limit. A finite primitive limit can still give a finite integral. Do not substitute an undefined endpoint into the original integrand.</p><h3>Choose what the quantity measures</h3>'''+D(r'\bar f=\frac1{b-a}\int_a^b f(x)\,dx',r'V=\pi\int_a^b y^2\,dx')+r'''<p>These prerequisite formulae are different from arc length and curved surface area. Check the variable with respect to which an average is requested.</p>''',
 ['Complete the square and identify the real interval.','Choose a direct inverse form or write a reversible substitution.','Transform the differential and both limits.','Integrate, applying a one-sided limit at an improper endpoint.','Differentiate the primitive to check the scale and branch.'],
 ['The derivative of an inner linear expression contributes a scale factor.','The principal square root is non-negative.','Change limits only when the integration variable changes.','An infinite endpoint value of the integrand does not prove divergence.','A mean, a volume and a surface area use different integrands.'],[
 E('T1','1 · Complete the square first',r'<p>Evaluate \(\int_1^3(16-(x-1)^2)^{-1/2}\,dx\).</p>',D(r'u=x-1,\qquad0\le u\le2',r'\int_0^2\frac{du}{\sqrt{16-u^2}}',r'=\left[\sin^{-1}\frac u4\right]_0^2=\frac\pi6')+'<p>The root is positive throughout the interval. No extra factor appears because du=dx.</p>','integral',f='1/sqrt(16-(x-1)**2)',lo='1',hi='3',value='pi/6'),
 E('T2','2 · A linear scale in a hyperbolic inverse',r'<p>Find \(\int(9+4x^2)^{-1/2}\,dx\).</p>',D(r'u=2x,\qquad dx=\frac12du',r'\int\frac{dx}{\sqrt{9+4x^2}}',r'=\frac12\sinh^{-1}(\frac{2x}{3})+C')+'<p>The factor 1/2 comes from the differential. Differentiate the result to check it.</p>','primitive',f='1/sqrt(9+4*x**2)',primitive='asinh(2*x/3)/2'),
 E('T3','3 · A convergent improper endpoint',r'<p>Evaluate \(\int_2^{5/2}(x^2-4)^{-1/2}\,dx\).</p>',D(r'x=2\cosh u,\qquad0<u\le\ln2',r'\frac{dx}{\sqrt{x^2-4}}=du\quad(u>0)',r'\lim_{\varepsilon\downarrow0}\int_{2+\varepsilon}^{5/2}\frac{dx}{\sqrt{x^2-4}}=\ln2')+'<p>At the upper limit cosh u=5/4, so u=ln2. At the lower limit u tends to zero. The singularity is integrable.</p>','integral',f='1/sqrt(x**2-4)',lo='2',hi='5/2',value='log(2)'),
 E('T4','4 · A hyperbolic substitution for a root',r'<p>Evaluate \(\int_0^{3/2}\sqrt{x^2+4}\,dx\).</p>',D(r'x=2\sinh u,\quad0\le u\le\ln2',r'\sqrt{x^2+4}\,dx=4\cosh^2u\,du',r'\int4\cosh^2u\,du=2u+\sinh2u',r'\int_0^{3/2}\sqrt{x^2+4}\,dx',r'=2\ln2+\frac{15}{8}')+'<p>Use cosh²u=(1+cosh2u)/2 and retain the transformed limits.</p>','integral',f='sqrt(x**2+4)',lo='0',hi='3/2',value='2*log(2)+15/8')])
L('reduction','Algebraic and exponential reduction formulae','Derive a recurrence, then start from the correct base case.',
 'Establish endpoint-aware recurrences and use them without accumulating rounding errors.',before('techniques')+'<p>Some written extensions use induction to establish a coefficient formula or a bound. Review <a href="/courses/maths4u-9231-fp1/topics/fp1_induction_sums">proof by induction</a> before those parts.</p>',
 r'''<h3>A recurrence is an identity between integrals</h3><p>For a family Iₙ, choose an integration-by-parts step or differentiate a suitable product. Rewrite its derivative using the family integrands, integrate over exactly the given interval, and evaluate the boundary term. State the indices for which every term is defined.</p>'''+D(r'H_n^{\prime}(x)=A_n f_n(x)+B_n f_{n-1}(x)',r'A_nI_n+B_nI_{n-1}=H_n(b)-H_n(a)')+r'''<h3>The boundary term may depend on n</h3><p>Do not erase a lower endpoint merely because one example made it zero. A factor xⁿ vanishes at zero when n&gt;0, but not when n=0. This is one reason the recurrence can have a stricter index range than the integral definition.</p><h3>Match the starting index to the step</h3><p>A step of one uses I₀ or I₁ as appropriate; a step of two splits the family into odd and even chains. Compute each needed base integral directly. For an indefinite family include an arbitrary constant in the final antiderivative.</p><h3>Carry evidence into later conclusions</h3><p>For an induction claim, state the base case, assume the result at the previous relevant index, and insert it into the proved recurrence. A numerical initial value has an error: a linear recurrence propagates that error by the absolute value of its coefficient. Round only once at the end.</p>''',
 ['Write the family and its valid indices.','Differentiate a useful product or integrate by parts.','Express the result using family members and evaluate both boundaries.','Find the necessary base integral and follow the correct parity chain.','Keep exact values and justify any bound or propagated error.'],
 ['A recurrence without its boundary term is generally false.','An n=0 case can differ from the n≥1 cases.','A two-step recurrence needs a base of the same parity.','An induction proof requires both a base and a general step.','Do not round each intermediate recurrence value.'],[
 E('R1','1 · A logarithmic family',r'<p>Let \(I_n=\int_1^{e^3}(\ln x)^n\,dx\). Derive a recurrence and find I₂.</p>',D(r'I_n=3^ne^3-nI_{n-1}\quad(n\ge1)',r'I_0=e^3-1,\qquad I_1=2e^3+1',r'I_2=5e^3-2')+'<p>Take u=(ln x)ⁿ and dv=dx. The lower endpoint contribution is zero only for n≥1.</p>','recurrence',f='log(x)**n',H='x*log(x)**n',coefficients={'0':'1','-1':'n'},lo='1',hi='exp(3)',boundary='3**n*exp(3)',target=2,value='5*exp(3)-2'),
 E('R2','2 · A rational-root family',r'<p>For \(J_n=\int_0^1(1+x^2)^{-n}\,dx\), derive a recurrence and evaluate J₂.</p>',D(r'\frac d{dx}\{x(1+x^2)^{-n}\}',r'=(1-2n)(1+x^2)^{-n}',r'\quad+2n(1+x^2)^{-n-1}',r'(1-2n)J_n+2nJ_{n+1}=2^{-n}',r'J_1=\frac\pi4,\qquad J_2=\frac14+\frac\pi8')+'<p>The recurrence holds for n≥1. Solve it for Jₙ₊₁ to move towards the requested integral.</p>','recurrence',f='(1+x**2)**(-n)',H='x*(1+x**2)**(-n)',coefficients={'0':'1-2*n','1':'2*n'},lo='0',hi='1',boundary='2**(-n)',target=2,value='1/4+pi/8'),
 E('R3','3 · A positive integral gives an exponential bound',r'<p>Let \(K_n=\int_0^1(1-x)^ne^x\,dx\). Find K₂ and use 0&lt;K₂&lt;1/2 to bound e.</p>',D(r'K_n-nK_{n-1}=-1\quad(n\ge1)',r'K_0=e-1,\quad K_1=e-2',r'K_2=2e-5,\qquad\frac52<e<\frac{11}{4}')+'<p>On 0&lt;x&lt;1, (1−x)eˣ&lt;1 because its derivative is −xeˣ&lt;0. Therefore 0&lt;(1−x)²eˣ&lt;1−x. Integrate to obtain the strict bound before rearranging.</p>','recurrence',f='(1-x)**n*exp(x)',H='(1-x)**n*exp(x)',coefficients={'0':'1','-1':'-n'},lo='0',hi='1',boundary='-1',target=2,value='2*E-5'),
 E('R4','4 · Propagating an input error',r'<p>A proved recurrence gives \(J_2=\frac16+\frac12J_1\) and \(J_3=\frac1{36}+\frac34J_2\). If the supplied J₁ has error at most 10⁻⁶, bound the induced error in J₃.</p>',D(r'J_3=\frac{11}{72}+\frac38J_1',r'|\Delta J_3|\le\frac38\times10^{-6}')+'<p>The constants contribute no input error. Multiply the two recurrence coefficients, then take the absolute value. This excludes any separate final-output rounding.</p>','error',coefficient='3/8',bound='3/8000000')])
L('trigonometric','Trigonometric and hyperbolic reductions','Use identities to turn derivatives into the integral family.',
 'Derive and apply reductions involving trigonometric and hyperbolic powers.',before('reduction'),
 r'''<h3>Choose a product that lowers a power</h3><p>For powers of sine, a product sinⁿ⁻¹x cos x produces both sinⁿx and sinⁿ⁻²x after differentiation and use of cos²x=1−sin²x. State n≥2 and evaluate the endpoints. The same idea works with hyperbolic identities, but their signs differ.</p>'''+D(r'\cos^2x=1-\sin^2x',r'\cosh^2x=1+\sinh^2x',r'\operatorname{sech}^2x=1-\tanh^2x')+r'''<h3>A frequency is part of the differential</h3><p>For sin(kx), derivatives and primitives introduce k and 1/k. A substitution u=kx changes the limits and gives dx=du/k. Keep these scale factors when a recurrence is used in a volume or another integral application.</p><h3>Sometimes subtract before integrating</h3><p>Neighbouring integrands can have a much simpler difference or sum. For example, cancelling a factor with 1−sin²x can leave a direct substitution. This can give a first-step recurrence without integration by parts.</p><h3>Choose the correct chain and domain</h3><p>An even power target and an odd power target may have different base integrals. Secant and cotangent families must avoid poles on the integration interval, or be handled as improper integrals with justified convergence. Do not use a recurrence to assign a finite number to a divergent integral.</p>''',
 ['Differentiate the suggested product or combine neighbouring integrands.','Apply the matching trigonometric or hyperbolic identity.','Keep the frequency factors and endpoint values.','State valid indices and find the required odd or even base.','Evaluate exactly, checking positivity when the integrand is non-negative.'],
 ['Circular and hyperbolic identities have different signs.','Do not lose the frequency in sin(kx) or cosh(kx).','A recurrence stepping by two preserves parity.','Check for poles before evaluating a definite integral.','A non-negative integrand cannot have a negative integral.'],[
 E('H1','1 · A sine-power reduction',r'<p>Let \(I_n=\int_0^{\pi/2}\sin^nx\,dx\). Derive the reduction and find I₄.</p>',D(r'\frac d{dx}(\sin^{n-1}x\cos x)',r'=(n-1)\sin^{n-2}x-n\sin^nx',r'nI_n=(n-1)I_{n-2}\quad(n\ge2)',r'I_0=\frac\pi2,\quad I_2=\frac\pi4,\quad I_4=\frac{3\pi}{16}')+'<p>Both product endpoints vanish for n≥2. The even chain starts from I₀.</p>','recurrence',f='sin(x)**n',H='sin(x)**(n-1)*cos(x)',coefficients={'0':'-n','-2':'n-1'},lo='0',hi='pi/2',boundary='0',target=4,value='3*pi/16'),
 E('H2','2 · A cosh family with a non-zero boundary',r'<p>Let \(C_n=\int_0^{\ln3}\cosh^nx\,dx\). Derive a recurrence and find C₂.</p>',D(r'nC_n-(n-1)C_{n-2}',r'=\frac43\left(\frac53\right)^{n-1}\quad(n\ge2)',r'C_0=\ln3,\qquad C_2=\frac{10}{9}+\frac12\ln3')+'<p>Differentiate sinh x coshⁿ⁻¹x and replace sinh²x by cosh²x−1. The upper endpoint uses sinh(ln3)=4/3 and cosh(ln3)=5/3.</p>','recurrence',f='cosh(x)**n',H='sinh(x)*cosh(x)**(n-1)',coefficients={'0':'n','-2':'-(n-1)'},lo='0',hi='log(3)',boundary='4/3*(5/3)**(n-1)',target=2,value='10/9+log(3)/2'),
 E('H3','3 · Subtract neighbouring integrands',r'<p>Let \(A_n=\int_0^{\pi/6}\sin^{2n}x/\cos x\,dx\). Derive Aₙ−Aₙ₊₁ and find A₁.</p>',D(r'A_n-A_{n+1}=\int_0^{\pi/6}\sin^{2n}x\cos x\,dx',r'=\frac{2^{-(2n+1)}}{2n+1}\quad(n\ge0)',r'A_0=\frac12\ln3,\qquad A_1=\frac12\ln3-\frac12')+'<p>The subtraction supplies cos²x in the numerator. Then u=sin x gives a power integral.</p>','difference',f='sin(x)**(2*n)/cos(x)',lo='0',hi='pi/6',delta='2**(-(2*n+1))/(2*n+1)',target=1,value='log(3)/2-1/2'),
 E('H4','4 · A scaled prerequisite volume',r'<p>The region under \(y=3\sin^2(2x)\) for \(0\le x\le\pi/4\) is rotated about the x-axis. Find its volume.</p>',D(r'V=9\pi\int_0^{\pi/4}\sin^4(2x)\,dx',r'=\frac{9\pi}{2}\int_0^{\pi/2}\sin^4u\,du',r'=\frac{27\pi^2}{32}')+'<p>The square on y produces sine to the fourth power; u=2x contributes 1/2. Use the previously proved even sine recurrence.</p>','integral',f='9*pi*sin(2*x)**4',lo='0',hi='pi/4',value='27*pi**2/32')])
L('arcs','Arc length in Cartesian, parametric and polar form','Integrate speed, keeping its non-negative branch.',
 'Set up and evaluate arc lengths without assuming monotone horizontal motion.',before('trigonometric')+'<p>Review <a href="/courses/maths4u-9231-fp2/topics/fp2_differentiation_parametric">parametric derivatives</a> and <a href="/courses/maths4u-9231-fp1/topics/fp1_polar_areas">polar coordinates</a>. A polar arc-length application uses the formula derived here.</p>',
 r'''<h3>A small displacement has a length</h3>'''+D(r'ds=\sqrt{dx^2+dy^2}',r'L=\int_a^b\sqrt{1+(y^{\prime})^2}\,dx',r'L=\int_\alpha^\beta\sqrt{(X^{\prime})^2+(Y^{\prime})^2}\,dt')+r'''<p>Use the first form for a single-valued y(x) over increasing x. The parametric speed remains non-negative even if X′ changes sign or is zero. The integral measures the path traversed; check whether the chosen parameter interval retraces a curve.</p><h3>Perfect squares still need a sign check</h3><p>Algebra may give speed²=g(t)². Then speed=|g(t)|. Remove the absolute value only after examining g on the whole interval, and split where necessary. An isolated zero speed does not by itself prevent a finite length.</p><h3>Polar length follows from Cartesian coordinates</h3><p>Differentiate X=r cos θ and Y=r sin θ. The cross terms cancel when the derivative squares are added.</p>'''+D(r'\left(\frac{ds}{d\theta}\right)^2=r^2+\left(\frac{dr}{d\theta}\right)^2',r'L=\int_\alpha^\beta\sqrt{r^2+(r^{\prime})^2}\,d\theta')+r'''<h3>Length is different from area</h3><p>A polar area uses half the integral of r²; it does not give a length. Keep the original endpoints and symmetry factors explicit. Units for a length are linear units.</p>''',
 ['Identify the representation and the exact parameter interval.','Differentiate each coordinate before squaring.','Simplify the speed squared, then check the square-root sign.','Integrate the non-negative speed over one traversal.','Check endpoints, symmetry factors and linear units.'],
 ['For parametric length use speed, not dy/dx alone.','The square root of a square is an absolute value.','Negative horizontal velocity does not give negative length.','A polar area formula is not an arc-length formula.','Check that a parameter interval does not retrace the same arc.'],[
 E('A1','1 · A Cartesian power curve',r'<p>Find the length of \(y=\frac23x^{3/2}\) from x=0 to x=3.</p>',D(r'y^{\prime}=\sqrt x,\qquad\frac{ds}{dx}=\sqrt{1+x}',r'L=\left[\frac23(1+x)^{3/2}\right]_0^3=\frac{14}{3}')+'<p>The lower endpoint is included by continuity of the speed.</p>','arc',X='t',Y='2*t**(3/2)/3',lo='0',hi='3',speed='sqrt(1+t)',value='14/3'),
 E('A2','2 · A perfect-square parametric speed',r'<p>Find the length for \(x=t^2\), \(y=t-t^3/3\), 0≤t≤2.</p>',D(r'X^{\prime}=2t,\qquad Y^{\prime}=1-t^2',r'\frac{ds}{dt}=\sqrt{4t^2+(1-t^2)^2}=1+t^2',r'L=\left[t+\frac{t^3}{3}\right]_0^2=\frac{14}{3}')+'<p>Although Y′ changes sign, speed remains positive. This parametrisation is not a graph with monotone y, but the length formula still applies.</p>','arc',X='t**2',Y='t-t**3/3',lo='0',hi='2',speed='1+t**2',value='14/3'),
 E('A3','3 · A hyperbolic profile',r'<p>Find the length of \(y=4\cosh(x/4)\) on 0≤x≤4ln2.</p>',D(r'y^{\prime}=\sinh(x/4)',r'\sqrt{1+(y^{\prime})^2}=\cosh(x/4)',r'L=4\sinh(\ln2)=3')+'<p>Cosh is positive, so the principal square root has no sign ambiguity.</p>','arc',X='t',Y='4*cosh(t/4)',lo='0',hi='4*log(2)',speed='cosh(t/4)',value='3'),
 E('A4','4 · A polar spiral',r'<p>Find the length of \(r=3e^{2\theta}\), 0≤θ≤ln2.</p>',D(r'r^{\prime}=6e^{2\theta}',r'\frac{ds}{d\theta}=3\sqrt5e^{2\theta}',r'L=\frac{3\sqrt5}{2}(4-1)=\frac{9\sqrt5}{2}')+'<p>The exponential is positive throughout. Use polar speed, not the polar area integrand.</p>','polar_arc',r='3*exp(2*t)',lo='0',hi='log(2)',speed='3*sqrt(5)*exp(2*t)',value='9*sqrt(5)/2')])
L('surfaces','Curved surfaces of revolution','Multiply a small arc length by its circumference.',
 'Calculate curved surface areas using the distance from the stated rotation axis.',before('arcs'),
 r'''<h3>A narrow strip makes a curved band</h3><p>Rotating an arc element ds at distance ρ from the axis gives dS=2πρ ds. The radius is a distance, so it is non-negative. The result is the curved area; end discs are included only if a question explicitly asks for them.</p>'''+D(r'S=2\pi\int\rho\,ds',r'S_x=2\pi\int_\alpha^\beta|Y(t)|\sqrt{X^{\prime}(t)^2+Y^{\prime}(t)^2}\,dt',r'S_y=2\pi\int_\alpha^\beta|X(t)|\sqrt{X^{\prime}(t)^2+Y^{\prime}(t)^2}\,dt')+r'''<h3>Choose the radius before integrating</h3><p>About the x-axis use |y|; about the y-axis use |x|. For a horizontal axis y=c, use |y−c|. If that expression changes sign, split at every crossing. An unsplit signed integral can cancel two positive areas.</p><h3>Simplify the speed first</h3><p>The derivative squares may combine into a perfect square, especially for hyperbolic or parametric curves. Prove its sign before removing a root. Then integrate radius times speed, which may need a second substitution or a reduction formula.</p><h3>Check the surface being measured</h3><p>A parametrisation that retraces an arc can count the same surface more than once. Confirm one traversal of the generating arc and whether distinct bands overlap. Units for surface area are square units. Volume uses discs or shells and has cubic units.</p>''',
 ['State the axis and the non-negative radius.','Find speed using the arc-length formula.','Split the interval at radius sign changes.','Integrate 2π times radius times speed.','Include only the requested curved surface and check square units.'],
 ['Use distance from the axis rather than a signed coordinate.','The y-axis needs |x|, not |y|.','Do not substitute the volume formula π∫y²dx.','End discs are separate from the curved surface.','A retraced arc can count a surface twice.'],[
 E('S1','1 · A straight generator',r'<p>Rotate \(y=2x\), 0≤x≤3, about the x-axis. Find the curved area.</p>',D(r'\rho=2x,\qquad ds=\sqrt5\,dx',r'S=4\pi\sqrt5\int_0^3x\,dx=18\pi\sqrt5')+'<p>This agrees with π times base radius 6 times slant height 3√5. The base disc is not included.</p>','surface',X='t',Y='2*t',lo='0',hi='3',axis='x',speed='sqrt(5)',value='18*pi*sqrt(5)'),
 E('S2','2 · A catenary surface',r'<p>Rotate \(y=2\cosh(x/2)\), 0≤x≤2ln2, about the x-axis.</p>',D(r'S=4\pi\int_0^{2\ln2}\cosh^2(x/2)\,dx',r'=4\pi\left[\frac x2+\frac{\sinh x}{2}\right]_0^{2\ln2}',r'=4\pi\ln2+\frac{15\pi}{4}')+'<p>The speed is cosh(x/2), while the radius is twice this value. These are separate factors.</p>','surface',X='t',Y='2*cosh(t/2)',lo='0',hi='2*log(2)',axis='x',speed='cosh(t/2)',value='4*pi*log(2)+15*pi/4'),
 E('S3','3 · Rotation about the vertical axis',r'<p>Rotate \(x=t^2\), \(y=t-t^3/3\), 0≤t≤1, about the y-axis.</p>',D(r'\rho=t^2,\qquad\frac{ds}{dt}=1+t^2',r'S=2\pi\int_0^1(t^2+t^4)\,dt=\frac{16\pi}{15}')+'<p>The vertical axis makes x the radius. Inserting y instead would calculate a different surface.</p>','surface',X='t**2',Y='t-t**3/3',lo='0',hi='1',axis='y',speed='1+t**2',value='16*pi/15'),
 E('S4','4 · Split where the radius changes sign',r'<p>Rotate \(x=t\), \(y=t-1\), 0≤t≤3, about the x-axis.</p>',D(r'S=2\pi\sqrt2\int_0^3|t-1|\,dt',r'=2\pi\sqrt2\left(\int_0^1(1-t)\,dt',r'\quad+\int_1^3(t-1)\,dt\right)=5\pi\sqrt2')+'<p>The two cones occupy different x-intervals, so their curved areas add. A signed radius would incorrectly cancel some area.</p>','surface',X='t',Y='t-1',lo='0',hi='3',axis='x',speed='sqrt(2)',split='1',value='5*pi*sqrt(2)')])
L('limits','Rectangle estimates, sums and limits','Use monotonicity to justify the direction of every bound.',
 'Build lower and upper sums, squeeze their limits and justify series comparisons.',before('surfaces')+'<p>Review arithmetic, geometric and power sums and the squeeze principle. Maclaurin estimates appear in one written extension; use <a href="/courses/maths4u-9231-fp2/topics/fp2_differentiation_maclaurin">the preceding differentiation chapter</a> when needed.</p>',
 r'''<h3>The rectangle width is part of the sum</h3><p>Divide [a,b] into N equal intervals of width h=(b−a)/N. For a continuous increasing function, left endpoints give the lower sum Lₙ and right endpoints give the upper sum Uₙ. For a decreasing function these choices reverse.</p>'''+D(r'L_N\le\int_a^bf(x)\,dx\le U_N',r'U_N-L_N=h|f(b)-f(a)|')+r'''<p>The inequalities are strict when the function is strictly monotone and the intervals have positive width. If h tends to zero, both bounds approach the integral. First rewrite a sum to identify both its sample points and its width.</p><h3>Unit rectangles compare finite series</h3><p>For positive decreasing f on [m,N], the left and right unit-width rectangles bound the integral. Isolating endpoints gives useful bounds for the complete finite sum.</p>'''+D(r'J_N=\int_m^Nf(x)\,dx',r'J_N+f(N)\le\sum_{r=m}^Nf(r)\le J_N+f(m)')+r'''<p>For increasing f, these endpoint corrections reverse. Prove monotonicity on the whole comparison interval; a function with a maximum may need a later starting point.</p><h3>Limits do not preserve strictness automatically</h3><p>Positive increasing partial sums with a uniform upper bound converge. A strict finite-N inequality normally gives only a non-strict bound after taking a limit. To retain strictness, exhibit a fixed positive gap that survives for all later N. To prove divergence, a lower bound tending to infinity is sufficient.</p><h3>Accuracy thresholds need the right integer</h3><p>For a gap C/N, a non-strict target allows equality; a strict target does not. Check the proposed least integer and its predecessor. A bound on the gap is different from the actual error of a particular rectangle sum.</p>''',
 ['Identify width, endpoints and the function represented by the sum.','Prove the required monotonicity on the stated interval.','Draw or describe which rectangles lie above and below.','Simplify the sums or bound their gap, including endpoint terms.','Take limits with justified inequality signs and check integer thresholds.'],
 ['Do not omit the rectangle width.','Right endpoints are upper heights only for an increasing function.','Unit-rectangle comparisons need endpoint corrections.','Strict finite bounds can become non-strict at the limit.','For a strict accuracy target, equality is insufficient.'],[
 E('L1','1 · Exact polynomial rectangle sums',r'<p>Find Lₙ,Uₙ and their common limit for \(f(x)=x^2+x\) on [0,1].</p>',D(r'f^{\prime}(x)=2x+1>0',r'U_N=\frac{(N+1)(5N+1)}{6N^2}',r'L_N=\frac{(N-1)(5N-1)}{6N^2}',r'U_N-L_N=\frac2N,\qquad\lim L_N=\lim U_N=\frac56')+'<p>Use sample points r/N and width 1/N, then the formulae for the first and second powers of r.</p>','rectangles',f='x**2+x',upper='(n+1)*(5*n+1)/(6*n**2)',lower='(n-1)*(5*n-1)/(6*n**2)',limit='5/6'),
 E('L2','2 · A strict accuracy target',r'<p>For \(f(x)=5^x\) on [0,1], find the least N with Uₙ−Lₙ&lt;1/500.</p>',D(r'U_N-L_N=\frac{5-1}{N}=\frac4N',r'\frac4N<\frac1{500}\quad\Longleftrightarrow\quad N>2000',r'N_{\min}=2001')+'<p>At N=2000 the gap equals the target, which does not satisfy the strict inequality.</p>','threshold',f='5**x',target='1/500',strict=True,value=2001),
 E('L3','3 · A convergent reciprocal series',r'<p>Use \(f(x)=x^{-2}\) on [1,N] to bound \(S_N=\sum_{r=1}^Nr^{-2}\), N≥2. Deduce convergence.</p>',D(r'\int_1^N x^{-2}\,dx=1-\frac1N',r'1-\frac1N+\frac1{N^2}<S_N<2-\frac1N',r'1\le\sum_{r=1}^\infty r^{-2}\le2')+'<p>The positive partial sums increase and remain bounded by 2. The finite strict comparisons justify non-strict limiting bounds; a stricter claim would require further evidence.</p>','series_bounds',f='1/x**2',start=1,lower='1-1/n+1/n**2',upper='2-1/n',limit_lower='1',limit_upper='2'),
 E('L4','4 · A sum represented by an inverse function',r'<p>Find \(\lim_{N\to\infty}\sum_{r=1}^N\frac{N}{N^2+r^2}\).</p>',D(r'\sum_{r=1}^N\frac{N}{N^2+r^2}',r'=\frac1N\sum_{r=1}^N\frac1{1+(r/N)^2}',r'\lim R_N=\int_0^1\frac{dx}{1+x^2}=\frac\pi4')+'<p>This is a right-endpoint lower sum for a strictly decreasing function. The upper-minus-lower gap is 1/(2N), so both have the same limit.</p>','integral',f='1/(1+x**2)',lo='0',hi='1',value='pi/4')])
